        public string AddBracket(string strparm)
        {
            string temp = "";
            if (strparm != "")
            {
                int count = 0;
                string[] Arrstring = strparm.Split('/');
                foreach (string str in Arrstring)
                {
                    if (count < 3)
                    { temp += "[" + str + "]"; }
                    else
                    { temp += str; }
                    if (count != Arrstring.Length - 1)
                    { temp = temp + "/"; }
                    count++;
                }
            }
            return temp;
        }

