        public long InsertLog(long dblParentSrNo, string strReqSrc, string strReqID, string strRequest, string strResponse, string strException, string strUpdateBy, SqlConnection ObjConnection)
        {
            long srNo = 0;
            //string strDebug = string.IsNullOrWhiteSpace(ConfigurationManager["DebugLog"]) ? "" : ConfigurationManager["DebugLog"].Trim();
            string strsql = "";
            if (!fnchkTable("tbl_GenericAPIDebugLog"))
            {
                strsql = "CREATE TABLE tbl_GenericAPIDebugLog(";
                strsql += "[SerialNo] [int] IDENTITY(1,1) NOT NULL,";
                strsql += "[ParentSerialNo] [int] NOT NULL,";
                strsql += "[RequestSource] [varchar](50) NOT NULL,";
                strsql += "[RequestUniqueID] [varchar](100) NOT NULL,";
                strsql += "[RequestString] [varchar](max) NOT NULL,";
                strsql += "[ResponseString] [varchar](max) NOT NULL,";
                strsql += "[ExceptionMessage] [varchar](max) NOT NULL,";
                strsql += "[UpdateBy] [varchar](50) NOT NULL,";
                strsql += "[UpdateTimeStamp] [datetime] NOT NULL,";
                strsql += " CONSTRAINT [PK_tbl_GenericAPIDebugLog] PRIMARY KEY NONCLUSTERED ";
                strsql += "(SerialNo)";
                strsql += ") ON [PRIMARY] TEXTIMAGE_ON [PRIMARY]";
                ExecuteSQL(strsql, ObjConnection);
            }

            strsql = "insert into tbl_GenericAPIDebugLog(ParentSerialNo, RequestSource, RequestUniqueID, RequestString, ResponseString, ExceptionMessage, UpdateBy, UpdateTimeStamp) values(@ParentSerialNo , @RequestSource, @RequestUniqueID, @RequestString, '', @ExceptionMessage, '', GETDATE())";
            using (SqlCommand command = new SqlCommand(strsql, ObjConnection))
            {
                command.Parameters.AddWithValue("@ParentSerialNo", dblParentSrNo);
                command.Parameters.AddWithValue("@RequestSource", strReqSrc);
                command.Parameters.AddWithValue("@RequestUniqueID", strReqID);
                command.Parameters.AddWithValue("@RequestString", strRequest);
                command.Parameters.AddWithValue("@ResponseString", strResponse);
                command.Parameters.AddWithValue("@ExceptionMessage", strException);
                command.Parameters.AddWithValue("@UpdateBy", strUpdateBy);

                command.ExecuteNonQuery();
            }

            strsql = "SELECT IDENT_CURRENT('tbl_GenericAPIDebugLog')";
            DataTable dt = OpenDataTableTmp(strsql, ObjConnection);
            if (dt.Rows.Count > 0)
            {
                srNo = Convert.ToInt64(dt.Rows[0][0]);
            }
            return srNo;
        }

        public void UpdateLog(long srNo, string strRequestUniqueID, string strResponse, string strException, SqlConnection ObjConnection)
        {
            //string strDebug = string.IsNullOrWhiteSpace(ConfigurationManager["DebugLog"]) ? "" : ConfigurationManager["DebugLog"].Trim();

            string strsql = "update tbl_GenericAPIDebugLog set ResponseString = @ResponseString, ExceptionMessage = @ExceptionMessage";
            if (!string.IsNullOrWhiteSpace(strRequestUniqueID))
            {
                strsql += ", RequestUniqueID = @RequestUniqueID";
            }
            strsql += " where SerialNo = @SerialNo";
            using (SqlCommand command = new SqlCommand(strsql, ObjConnection))
            {
                command.Parameters.AddWithValue("@ResponseString", strResponse);
                command.Parameters.AddWithValue("@ExceptionMessage", strException);
                if (!string.IsNullOrWhiteSpace(strRequestUniqueID))
                {
                    command.Parameters.AddWithValue("@RequestUniqueID", strRequestUniqueID);
                }
                command.Parameters.AddWithValue("@SerialNo", srNo);

                command.ExecuteNonQuery();
            }
        }

