                    DataTable dtCount = OpenDataTable("select count(*) from tbl_InsertUpdateXMLDropDownQuery where ModuleName = 'BILL' and ColumnName = 'Segment'");
                    if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                    {
                        strsql = @"INSERT INTO tbl_InsertUpdateXMLDropDownQuery ([ModuleName], [ColumnName], [DBQuery], [UserCode], [UpdateTimeStamp], [DBQueryType]) VALUES (N'BILL', N'Segment', N'select ''CASH'' as [Value], ''CASH'' as [DisplayName]
                                   UNION ALL
                                   select ''DERV'' as [Value], ''Derivative'' as [DisplayName]
                                   UNION ALL
                                   select ''CURR'' as [Value], ''Currency'' as [DisplayName]
                                   UNION ALL
                                   select ''COMM'' as [Value], ''Commodity'' as [DisplayName]', N'SA', GETDATE(), N'Q')";
                        ExecuteSQL(strsql, sqlCon);
                    }

                    dtCount = OpenDataTable("select count(*) from tbl_InsertUpdateXMLDropDownQuery where ModuleName = 'BILL' and ColumnName = 'SettlementNo'");
                    if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                    {
                        strsql = @"INSERT INTO tbl_InsertUpdateXMLDropDownQuery ([ModuleName], [ColumnName], [DBQuery], [UserCode], [UpdateTimeStamp], [DBQueryType]) VALUES (N'BILL', N'SettlementNo', N'DECLARE @ClearHouse VARCHAR(1) = ''''
                                   SELECT @ClearHouse = (CASE WHEN CH_ClgHs = ''N'' THEN ''N'' ELSE ''B'' END)
                                   FROM ClearingHouse(NOLOCK)
                                   WHERE CH_EffDt IN (
                                   SELECT MAX(CH_EffDt)
                                   FROM ClearingHouse
                                   WHERE CH_Segment = ''C''
                                   ) AND CH_Segment = ''C''
                                   SELECT se_stlmnt AS [Value], se_stlmnt AS [DisplayName]
                                   FROM Settlements(NOLOCK)
                                   WHERE Se_stdt = ''<<FromDate>>'' AND se_exchange = @ClearHouse
                                   AND ''<<Segment>>'' = ''CASH''
                                   ', N'SA', GETDATE(), N'Q')";
                        ExecuteSQL(strsql, sqlCon);
                    }

                    dtCount = OpenDataTable("select count(*) from tbl_InsertUpdateXMLDropDownQuery where ModuleName = 'PROFITLOSS' and ColumnName = 'Exchange'");
                    if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                    {
                        strsql = @"INSERT INTO tbl_InsertUpdateXMLDropDownQuery ([ModuleName], [ColumnName], [DBQuery], [UserCode], [UpdateTimeStamp], [DBQueryType]) VALUES (N'PROFITLOSS', N'Exchange', N'SELECT '''' AS [Value], ''ALL'' AS [DisplayName] UNION ALL SELECT LTRIM(RTRIM(ces_cd)) AS [Value], LTRIM(RTRIM(CES_Exchange)) + '' '' + LTRIM(RTRIM(CES_Segment)) AS [DisplayName]  
                                   FROM CompanyExchangeSegments(NOLOCK)  
                                   WHERE CASE WHEN RIGHT(ces_cd, 1) = ''F'' THEN ''Derv'' WHEN RIGHT(ces_cd, 1) = ''C'' THEN ''Cash'' 
                                   WHEN RIGHT(ces_cd, 1) = ''K'' THEN ''CURR'' ELSE ''Comm''     END = ''<<FILTER>>''  ', N'SA', GETDATE(), N'Q')";
                        ExecuteSQL(strsql, sqlCon);
