        public void CreateMrgpTables()
        {
            string strsql = "";
            //var db = new DataContext();
            DataTable dtCount = new DataTable();
            string strMarginType = mfnGetSysSplFeature("OPN") ? "OPN" : (mfnGetSysSplFeature("OPC") ? "OPC" : "");

            if (strMarginType == "OPN" || strMarginType == "OPC")
            {
                using (SqlConnection sqlCon = new SqlConnection(_connStr))
                {
                    sqlCon.Open();

                    if (!fnchkTable("tbl_GenericAPIDefinition", sqlCon))
                    {
                        strsql = "CREATE TABLE tbl_GenericAPIDefinition( ";
                        strsql += " [SerialNo] [int] IDENTITY(1,1) NOT NULL, ";
                        strsql += " [ProjectName] [varchar](50) NOT NULL, ";
                        strsql += " [ModuleName] [varchar](50) NOT NULL, ";
                        strsql += " [FunctionName] [varchar](50) NOT NULL, ";
                        strsql += " [ProcedureName] [varchar](1000) NOT NULL, ";
                        strsql += " [IsDebugEnabled] [varchar](1) NOT NULL, ";
                        strsql += " [IsActive] [varchar](1) NOT NULL, ";
                        strsql += " [APIDescription] [varchar](1000) NOT NULL, ";
                        strsql += " [AppServerFilePath] [varchar](255) NOT NULL, ";
                        strsql += " [Owner] [varchar](50) NOT NULL, ";
                        strsql += " [UpdateBy] [varchar](50) NOT NULL, ";
                        strsql += " [UpdateTimeStamp] [datetime] NOT NULL, ";
                        strsql += " CONSTRAINT [PK_tbl_GenericAPIDefinition] PRIMARY KEY CLUSTERED ";
                        strsql += " ( ";
                        strsql += " [ProjectName] ASC, ";
                        strsql += " [ModuleName] ASC, ";
                        strsql += " [FunctionName] ASC ";
                        strsql += " ) ";
                        strsql += " ) ";
                        ExecuteSQL(strsql, sqlCon);
                    }

                    if (strMarginType == "OPN")
                    {
                        dtCount = OpenDataTable("select count(*) from tbl_GenericAPIDefinition where ProjectName = 'TradeWebAPI' and ModuleName = 'MARGINPLEDGENSDL'");
                        if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                        {
                            strsql = @"INSERT INTO tbl_GenericAPIDefinition(ProjectName, ModuleName, FunctionName, ProcedureName, IsDebugEnabled, IsActive, APIDescription, AppServerFilePath, Owner, UpdateBy, UpdateTimeStamp) VALUES('TradeWebAPI', 'MARGINPLEDGENSDL', 'GetHolding', 'stpr_APIMARGINPLEDGE', 'Y', 'Y', '', '', '', '', GETDATE());
                                       INSERT INTO tbl_GenericAPIDefinition(ProjectName, ModuleName, FunctionName, ProcedureName, IsDebugEnabled, IsActive, APIDescription, AppServerFilePath, Owner, UpdateBy, UpdateTimeStamp) VALUES('TradeWebAPI', 'MARGINPLEDGENSDL', 'GETRESPONSENSDL', 'stpr_APIMARGINPLEDGE', 'Y', 'Y', '', '', '', '', GETDATE());
                                       INSERT INTO tbl_GenericAPIDefinition(ProjectName, ModuleName, FunctionName, ProcedureName, IsDebugEnabled, IsActive, APIDescription, AppServerFilePath, Owner, UpdateBy, UpdateTimeStamp) VALUES('TradeWebAPI', 'MARGINPLEDGENSDL', 'POSTDATA', 'stpr_APIMARGINPLEDGE', 'Y', 'Y', '', '', '', '', GETDATE());";
                            ExecuteSQL(strsql, sqlCon);
                        }
                    }
                    else
                    {
                        dtCount = OpenDataTable("select count(*) from tbl_GenericAPIDefinition where ProjectName = 'TradeWebAPI' and ModuleName = 'MARGINPLEDGECDSL'");
                        if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                        {
                            strsql = @"INSERT INTO tbl_GenericAPIDefinition(ProjectName, ModuleName, FunctionName, ProcedureName, IsDebugEnabled, IsActive, APIDescription, AppServerFilePath, Owner, UpdateBy, UpdateTimeStamp) VALUES('TradeWebAPI', 'MARGINPLEDGECDSL', 'GetHolding', 'stpr_APIMARGINPLEDGE', 'Y', 'Y', '', '', '', '', GETDATE());
                                       INSERT INTO tbl_GenericAPIDefinition(ProjectName, ModuleName, FunctionName, ProcedureName, IsDebugEnabled, IsActive, APIDescription, AppServerFilePath, Owner, UpdateBy, UpdateTimeStamp) VALUES('TradeWebAPI', 'MARGINPLEDGECDSL', 'GETRESPONSECDSL', 'stpr_APIMARGINPLEDGE', 'Y', 'Y', '', '', '', '', GETDATE());
                                       INSERT INTO tbl_GenericAPIDefinition(ProjectName, ModuleName, FunctionName, ProcedureName, IsDebugEnabled, IsActive, APIDescription, AppServerFilePath, Owner, UpdateBy, UpdateTimeStamp) VALUES('TradeWebAPI', 'MARGINPLEDGECDSL', 'POSTDATA', 'stpr_APIMARGINPLEDGE', 'Y', 'Y', '', '', '', '', GETDATE());
                                       INSERT INTO tbl_GenericAPIDefinition(ProjectName, ModuleName, FunctionName, ProcedureName, IsDebugEnabled, IsActive, APIDescription, AppServerFilePath, Owner, UpdateBy, UpdateTimeStamp) VALUES('TradeWebAPI', 'MARGINPLEDGECDSL', 'GetRepledge', 'stpr_APIMARGINPLEDGE', 'Y', 'Y', '', '', '', '', GETDATE());";
                            ExecuteSQL(strsql, sqlCon);
                        }
                    }

                    if (!fnchkTable("tbl_VendorAPISetting", sqlCon))
                    {
                        strsql = "CREATE TABLE tbl_VendorAPISetting( ";
                        strsql += " [SerialNo] [int] IDENTITY(1,1) NOT NULL, ";
                        strsql += " [APIVendorName] [varchar](50) NOT NULL  DEFAULT '', ";
                        strsql += " [APIName] [varchar](50) NOT NULL  DEFAULT '', ";
                        strsql += " [APIType] [varchar](50) NOT NULL  DEFAULT '', ";
                        strsql += " [APICallingType] [varchar](50) NOT NULL  DEFAULT '', ";
                        strsql += " [APIUrl] [varchar](200) NOT NULL  DEFAULT '', ";
                        strsql += " [APIContantType] [varchar](200) NOT NULL  DEFAULT '', ";
                        strsql += " [APIAuthToken] [varchar](200) NOT NULL  DEFAULT '', ";
                        strsql += " [FieldsForHeader] [varchar](max) NOT NULL  DEFAULT '', ";
                        strsql += " [FileFormat] [varchar](50) NOT NULL  DEFAULT '', ";
                        strsql += " [FileContantandPath] [nvarchar](max) NOT NULL  DEFAULT '', ";
                        strsql += " [FileName] [varchar](200) NOT NULL  DEFAULT '', ";
                        strsql += " [FilePassword] [varchar](200) NOT NULL  DEFAULT '', ";
                        strsql += " [RequestJson] [nvarchar](max) NOT NULL  DEFAULT '', ";
                        strsql += " [ResponseJson] [nvarchar](max) NOT NULL  DEFAULT '', ";
                        strsql += " [CallBackTag] [varchar](1) NOT NULL  DEFAULT '', ";
                        strsql += " [CallBackUrl] [varchar](100) NOT NULL  DEFAULT '', ";
                        strsql += " [CallBackRequestJson] [varchar](100) NOT NULL  DEFAULT '', ";
                        strsql += " [CallBackResponseJson] [varchar](100) NOT NULL  DEFAULT '', ";
                        strsql += " [IsActive] [varchar](1) NOT NULL  DEFAULT '', ";
                        strsql += " [UserCode] [varchar](50) NOT NULL  DEFAULT '', ";
                        strsql += " [UpdateTimeStamp] [datetime] NOT NULL  DEFAULT GETDATE() ";
                        strsql += " ) ";
                        ExecuteSQL(strsql, sqlCon);
                    }

                    if (strMarginType == "OPN")
                    {
                        dtCount = OpenDataTable("select count(*) from tbl_VendorAPISetting where APIVendorName = 'NSDL' and APIName = 'MARGINPLEDGE'", sqlCon);
                        if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                        {
                            strsql = @"INSERT INTO tbl_VendorAPISetting([APIVendorName], [APIName], [APIType], [APICallingType], [APIUrl], [APIContantType], [APIAuthToken], [FieldsForHeader], [FileFormat], [FileContantandPath], [FileName], [FilePassword], [RequestJson], [ResponseJson], [CallBackTag], [CallBackUrl], [CallBackRequestJson], [CallBackResponseJson], [IsActive], [UserCode], [UpdateTimeStamp]) VALUES(N'NSDL', N'MARGINPLEDGE', N'REST', N'POST', N'https://eservices-test.nsdl.com/mpi-service/v1/public/mpi/orders', N'multipart/form-data', N'', N'', N'', N'', N'', N'', N'requestor|requestorId|segment|exchangeCd|pledgeeDpId|pledgeeClientId|tmId|cmId|MPI|WEB', N'', N'', N'', N'', N'', N'Y', N'', GETDATE())";
                            ExecuteSQL(strsql, sqlCon);
                        }
                    }
                    else
                    {
                        dtCount = OpenDataTable("select count(*) from tbl_VendorAPISetting where APIVendorName = 'CDSL' and APIName = 'MARGINPLEDGE'", sqlCon);
                        if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                        {
                            strsql = @"INSERT INTO tbl_VendorAPISetting([APIVendorName], [APIName], [APIType], [APICallingType], [APIUrl], [APIContantType], [APIAuthToken], [FieldsForHeader], [FileFormat], [FileContantandPath], [FileName], [FilePassword], [RequestJson], [ResponseJson], [CallBackTag], [CallBackUrl], [CallBackRequestJson], [CallBackResponseJson], [IsActive], [UserCode], [UpdateTimeStamp]) VALUES(N'CDSL', N'MARGINPLEDGE', N'REST', N'POST', N'https://api.cdslindia.com/APIServices/pledgeapi/pledgesetup', N'multipart/form-data', N'', N'', N'', N'', N'', N'', N'pledgeidentifier|pledgeeboid|exid|entityidentifier|TMID|segmentid|cmid|ReasonCode', N'', N'', N'', N'', N'', N'Y', N'', GETDATE())";
                            ExecuteSQL(strsql, sqlCon);
                        }

                        dtCount = OpenDataTable("select count(*) from tbl_VendorAPISetting where APIVendorName = 'CDSL' and APIName = 'PLEDGEENQ'", sqlCon);
                        if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                        {
                            strsql = @"INSERT INTO tbl_VendorAPISetting([APIVendorName], [APIName], [APIType], [APICallingType], [APIUrl], [APIContantType], [APIAuthToken], [FieldsForHeader], [FileFormat], [FileContantandPath], [FileName], [FilePassword], [RequestJson], [ResponseJson], [CallBackTag], [CallBackUrl], [CallBackRequestJson], [CallBackResponseJson], [IsActive], [UserCode], [UpdateTimeStamp]) VALUES(N'CDSL', N'PLEDGEENQ', N'REST', N'POST', N'https://api.cdslindia.com/APIServices/pledgeapi/pledgestatus', N'application/json', N'', N'', N'', N'', N'', N'', N'pledgeeboid|aeskey', N'', N'', N'', N'', N'', N'Y', N'', GETDATE())";
                            ExecuteSQL(strsql, sqlCon);
                        }

                        dtCount = OpenDataTable("select count(*) from tbl_VendorAPISetting where APIVendorName = 'CDSL' and APIName = 'MARGINREPLEDGE'", sqlCon);
                        if (Convert.ToInt32(dtCount.Rows[0][0].ToString()) == 0)
                        {
                            strsql = @"INSERT INTO tbl_VendorAPISetting([APIVendorName], [APIName], [APIType], [APICallingType], [APIUrl], [APIContantType], [APIAuthToken], [FieldsForHeader], [FileFormat], [FileContantandPath], [FileName], [FilePassword], [RequestJson], [ResponseJson], [CallBackTag], [CallBackUrl], [CallBackRequestJson], [CallBackResponseJson], [IsActive], [UserCode], [UpdateTimeStamp]) VALUES(N'CDSL', N'MARGINREPLEDGE', N'REST', N'POST', N'https://api.cdslindia.com/MarginRepledgeAPI/Setup/v1.0', N'application/json', N'', N'', N'', N'', N'', N'', N'pledgeeboid|reasoncode|cmid|agrmntno', N'', N'', N'', N'', N'', N'Y', N'', GETDATE())";
                            ExecuteSQL(strsql, sqlCon);
                        }
                    }

                    CheckSP("Pledge");

                    if (Convert.ToInt16(fnFireQueryTradeWeb("WebParameter", "COUNT(0)", "sp_parmcd", "TRADEPLUSTEMPDB", true)) == 0)
                    {
                        strsql = "INSERT INTO WebParameter(sp_parmcd, sp_name, sp_sysvalue) VALUES('TRADEPLUSTEMPDB','TRADE PLUS 130 LEVEL','TRADEPLUSTEMPDB')";
                        ExecuteSQL(strsql, sqlCon);
                    }

                    if (strMarginType == "OPN")
                    {
                        if (Convert.ToInt16(fnFireQueryTradeWeb("WebParameter", "COUNT(0)", "sp_parmcd", "NSDLETOKEN", true)) == 0)
                        {
                            strsql = "INSERT INTO WebParameter(sp_parmcd, sp_name, sp_sysvalue) VALUES('NSDLETOKEN','NSDL EToken Details','<USERNAME>~<TOKENTYPE>~<TOKENSRNO>~<TOKENPASS>')";
                            ExecuteSQL(strsql, sqlCon);
                        }

                        if (Convert.ToInt16(fnFireQueryTradeWeb("WebParameter", "COUNT(0)", "sp_parmcd", "NSDLSIGURL", true)) == 0)
                        {
                            strsql = "INSERT INTO WebParameter(sp_parmcd, sp_name, sp_sysvalue) VALUES('NSDLSIGURL','EToken Signature Service URL','http://localhost:83')";
                            ExecuteSQL(strsql, sqlCon);
                        }
                    }
                    else
                    {
                        if (!fnchkTable("TBL_ClientMarginPledgeDtl", sqlCon))
                        {
                            strsql = "CREATE TABLE TBL_ClientMarginPledgeDtl( " +
                            " [SerialNo] [int] IDENTITY(1,1) NOT NULL, " +
                            " [ClientCode] [varchar](50) NOT NULL, " +
                            " [ScripCode] [varchar](30) NOT NULL, " +
                            " [Isin] [varchar](30) NOT NULL, " +
                            " [DPAccountNo] [varchar](30) NOT NULL, " +
                            " [RequestDate] [varchar](8) NOT NULL, " +
                            " [Qty] [money] NOT NULL, " +
                            " [StockValue] [money] NOT NULL, " +
                            " [CDSLReqNo] [varchar](16) NOT NULL, " +
                            " [PledgeFormNo] [varchar](16) NOT NULL, " +
                            " [PledgeIntRefNo] [varchar](16) NOT NULL, " +
                            " [ISINReqId] [varchar](24) NOT NULL, " +
                            " [ISINResId] [varchar](24) NOT NULL, " +
                            " [PSNNo] [varchar](24) NOT NULL, " +
                            " [PSNStatus] [varchar](60) NOT NULL, " +
                            " [ParentPSNNO] [varchar](20) NOT NULL, " +
                            " [ResponseCode] [varchar](20) NOT NULL, " +
                            " [ResponseMessage] [varchar](500) NOT NULL, " +
                            " [UpdateTimeStamp] [datetime] NOT NULL, " +
                            " [PledgeeboReqId] [varchar](16) NOT NULL, " +
                            " [PldgrdpIntRefno] [varchar](16) NOT NULL, " +
                            " [AgrmntNo] [varchar](20) NOT NULL, " +
                            " [RepledgeReqid] [varchar](20) NOT NULL " +
                            " ) ";
                            ExecuteSQL(strsql, sqlCon);
                        }

                        if (Convert.ToInt16(fnFireQueryTradeWeb("Sysparameter", "COUNT(0)", "sp_parmcd", "ThirdParty", true)) == 0)
                        {
