        public DateTime GetSqlCurrentDateTime()
        {
            DateTime currentDateTime;

            string query = "SELECT GETDATE()";

            using (SqlConnection conn = new SqlConnection(GetConnectionStr()))
            {
                using SqlCommand cmd = new SqlCommand(query, conn);
                conn.Open();
                currentDateTime = (DateTime)cmd.ExecuteScalar();
            }

            return currentDateTime;
        }

        public string SerializeToXml<T>(T obj, bool omitXmlDeclaration = false, bool indent = false, string encoding = "utf-8")
        {
            if (obj == null)
            {
                throw new ArgumentNullException(nameof(obj));
            }
            var xmlSerializer = new XmlSerializer(typeof(T));

            var xmlWriterSettings = new XmlWriterSettings
            {
                OmitXmlDeclaration = omitXmlDeclaration,
                Indent = indent,
                Encoding = Encoding.GetEncoding(encoding)
            };
            using (var stringWriter = new StringWriterWithEncoding(Encoding.GetEncoding(encoding)))
            {
                using (var xmlWriter = XmlWriter.Create(stringWriter, xmlWriterSettings))
                {
                    xmlSerializer.Serialize(xmlWriter, obj);
                    return stringWriter.ToString();
                }
            }
        }

        private class StringWriterWithEncoding : StringWriter
        {
            private readonly Encoding encoding;

            public StringWriterWithEncoding(Encoding encoding)
            {
                this.encoding = encoding;
            }
            public override Encoding Encoding => encoding;
        }

        public string CheckPasswordCondition(string newPassword, string dpid, string clientCode)
        {
            try
            {
                double intLastPass = Conversion.Val(GetWebParameter("PWDSAMECHK"));
                string Strsql = "";
                if (intLastPass > 0)
                {
                    if (!fnchkTable("Password_history"))
                    {
                        Strsql = "CREATE TABLE Password_history(";
                        Strsql += "[ph_srno] [numeric](18, 0) IDENTITY(1,1) NOT NULL,";
                        Strsql += "[ph_dpid] [char](8) NOT NULL,";
                        Strsql += "[ph_code] [char](8) NOT NULL,";
                        Strsql += "[ph_logintype] [char](1) NOT NULL,";
                        Strsql += "[ph_password] [char](10) NOT NULL,";
                        Strsql += "[mkrdt] [char](8) NOT NULL";
                        Strsql += ")";
                        ExecuteSQL(Strsql);
                    }
                }

                if (ConfigurationManager["IsTradeWeb"] == "C" || ConfigurationManager["IsTradeWeb"] == "E")
                {
                    string strPwdSetting = fnFireQueryTradeWeb("webparameter", "sp_sysvalue", "sp_parmcd", "PWDSETTING", true);
                    if (strPwdSetting != "")
                    {
                        string strPwdMinLen = strPwdSetting.Split('/')[0];
                        string strPwdFormat = strPwdSetting.Split('/')[1];
                        if (newPassword.Length < Convert.ToInt32(strPwdMinLen))
                        {
                            return "Password should contain minimum " + strPwdMinLen + " characters.";
                        }
                        if (strPwdFormat.Trim() == "Y")
                        {
                            int intPwdAlphaCnt = 0;
                            int intPwdNumCnt = 0;
                            int intPwdSplCnt = 0;
                            string strNewPwd = newPassword;
                            for (int i = 0; i <= strNewPwd.Length - 1; i++)
                            {
                                if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 65 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 90)
                                {
                                    intPwdAlphaCnt++;
                                }
                                else if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 97 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 122)
                                {
                                    intPwdAlphaCnt++;
                                }
                                else if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 48 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 57)
                                {
                                    intPwdNumCnt++;
                                }
                                else
                                {
                                    intPwdSplCnt++;
                                }
                            }
                            if (intPwdNumCnt == 0)
                            {
                                return "Password should contain at least one number.";
                            }
                            if (intPwdAlphaCnt == 0)
                            {
                                return "Password should contain at least one Alphabet.";
                            }
                            if (intPwdSplCnt == 0)
                            {
                                return "Password should contain at least one special character.";
                            }
                        }
                    }
                }

                if (ConfigurationManager["IsTradeWeb"] == "O")
                {
                    double intMinChar = Conversion.Val(GetSysParmSt("PWDMINCHR", ""));
                    string strAlphaNum = GetSysParmSt("PWDALPHANUM", "");

                    if (intMinChar > 0)
                    {
                        if (newPassword.Length < intMinChar)
                        {
                            return "Password should contain minimum " + intMinChar + " characters.";
                        }
                    }
                    if (strAlphaNum.Trim() == "Y")
                    {
                        int intPwdAlphaCnt = 0;
                        int intPwdNumCnt = 0;
                        int intPwdSplCnt = 0;

                        for (int i = 0; i <= newPassword.Length - 1; i++)
                        {
                            if (Strings.Asc(newPassword.Substring(i, 1)) >= 65 && Strings.Asc(newPassword.Substring(i, 1)) <= 90)
                            {
                                intPwdAlphaCnt++;
                            }
                            else if (Strings.Asc(newPassword.Substring(i, 1)) >= 97 && Strings.Asc(newPassword.Substring(i, 1)) <= 122)
                            {
                                intPwdAlphaCnt++;
                            }
                            else if (Strings.Asc(newPassword.Substring(i, 1)) >= 48 && Strings.Asc(newPassword.Substring(i, 1)) <= 57)
                            {
                                intPwdNumCnt++;
                            }
                            else
                            {
                                intPwdSplCnt++;
                            }
                        }
                        if (intPwdNumCnt == 0)
                        {
                            return "Password should contain at least one number.";
                        }
                        if (intPwdAlphaCnt == 0)
                        {
                            return "Password should contain at least one Alphabet.";
                        }
                        if (intPwdSplCnt == 0)
                        {
                            return "Password should contain at least one special character.";
                        }
                    }
                }

                /*if (intLastPass > 0)
                {
                    if (CheckPreviousPassword(intLastPass, dpid, clientCode, newPassword))
                    {
                        return "You cannot use any of the previous " + intLastPass + " passwords. Please set a different password.!";
                    }
                }*/

                int pwdMaxLenght = Convert.ToInt32(ExecuteSQLReturn("SELECT character_maximum_length as 'Max Length'  FROM information_schema.columns  WHERE table_name = 'Client_Master' and COLUMN_NAME='CM_PWD'"));
                if (newPassword.Length > pwdMaxLenght)
                {
                    return "Password maximum length should be " + pwdMaxLenght + " characters.";
                }
            }
            catch (Exception) { }

            return "";
        }

        public bool CheckPreviousPassword(double intLastPass, string strDPID, string strCode, string strNewPassword)
        {
            bool blnPwd = false;

            if (GetWebParameter("TWEBENCPWD") == "Y")
            {
                strNewPassword = Encrypt(strNewPassword);
            }

            string Strsql = "select top " + intLastPass + " ph_dpid, ph_code, ph_password from Password_history where ph_logintype='C' and ph_dpid = '" + strDPID + "' and ph_code='" + strCode + "' order by ph_srno desc";
            DataTable dtPass = OpenDataTable(Strsql);
            foreach (DataRow dr in dtPass.Rows)
            {
                if (dr["ph_password"].ToString().Trim() == strNewPassword)
                {
                    blnPwd = true;
                    break;
                }
            }
            return blnPwd;
        }

        public string AfterChangePasswordTblEntry(string newPassword, string dpid, string clientCode)
        {
            try
            {
                double intLastPass = Conversion.Val(GetWebParameter("PWDSAMECHK"));
                string strLastLoginDt = fnFireQueryTradeWeb("Client_master", "cm_lastlogindt", "cm_cd", clientCode, true);
                if (ConfigurationManager["IsTradeWeb"] != "O") //not live
                {
                    string Strsql = "Update LoginDetails set lg_lastLoginDt='" + strLastLoginDt + "',lg_RsetPwd='Y',lg_ChangePwd='Y',lg_LastRSetDt='" + DateTime.Now.ToString("yyyyMMdd").Trim() + "' where lg_cmcd='" + clientCode + "' and lg_companycode='" + dpid + "'";
                    ExecuteSQL(Strsql);
                }
                if (intLastPass > 0)
                {
                    if (GetWebParameter("TWEBENCPWD") == "Y")
                    {
                        newPassword = Encrypt(newPassword);
                    }

                    string Strsql = "Insert into Password_history(ph_dpid, ph_code, ph_logintype, ph_password, mkrdt) values('" + dpid + "', '" + clientCode + "', 'C', '" + newPassword + "', '" + DateTime.Now.ToString("yyyyMMdd") + "')";
                    ExecuteSQL(Strsql);
                }
            }
            catch (Exception)
            {
            }
            return "Success";
        }

        public dynamic SendSmsCommon(string clientCd, string strMsgTxt, string strMobileNo)
        {
            try
            {
                var strSMSParamVal = new string[5];
                string strSMSParameter = "SMSUSERID/SMSPWD/SMSSENDER/SMSLENGTH/SMSLINK";
                string strvalue = string.Empty;
                string strFromNo1 = "", strsql = "";
                string strFromNo2 = "";
                string strresponse = "";

                //CreateOTPMasterTable();

                if (ConfigurationManager["IsTradeWeb"] == "O")
                {
                    for (int i = 0; i <= 4; i++)
                    {
                        strvalue = strSMSParameter.Split('/')[i];
                        strSMSParamVal[i] = fnFireQuery("sysparameter", "SP_SYSVALUE", "sp_parmcd", strvalue, true);
                    }
                }
                else
                {
                    if (Convert.ToInt32(fnFireQueryTradeWeb("webparameter", "count(0)", "sp_parmcd", "SMSSETUP", true)) > 0)
                    {
                        strvalue = fnFireQueryTradeWeb("webparameter", "SP_SYSVALUE", "sp_parmcd", "SMSSETUP", true);
                        strSMSParamVal[0] = strvalue.Split('~')[1];
                        strSMSParamVal[1] = strvalue.Split('~')[2];
                        strSMSParamVal[2] = strvalue.Split('~')[3];
                        strSMSParamVal[3] = strvalue.Split('~')[4];
                        strSMSParamVal[4] = strvalue.Split('~')[0];
                    }
                }
                string strURLLink = strSMSParamVal[4];

                if (strURLLink.IndexOf("<USERID>") != -1 & !string.IsNullOrEmpty(strSMSParamVal[0].Trim()))
                {
                    strURLLink = strURLLink.Replace("<USERID>", strSMSParamVal[0].Trim());
                }
                if (strURLLink.IndexOf("<PASSWORD>") != -1 & !string.IsNullOrEmpty(strSMSParamVal[1].Trim()))
                {
                    strURLLink = strURLLink.Replace("<PASSWORD>", strSMSParamVal[1].Trim());
                }
                if (string.IsNullOrEmpty(strSMSParamVal[2].Trim()))
                {
                    if (strURLLink.IndexOf("<SENDERID>") != -1)
                    {
                        strURLLink = strURLLink.Replace("<SENDERID>", strSMSParamVal[2].Trim());
                    }
                }
                else
                {
                    strFromNo1 = strSMSParamVal[2].Trim();
                    if (strFromNo1.IndexOf("|") != -1)
                    {
                        strFromNo2 = strFromNo1.Split("|")[1];
                        strFromNo1 = strFromNo1.Split("|")[0];
                    }
                    else
                    {
                        strFromNo1 = Strings.Left(strFromNo1.Trim(), 10);
                        strFromNo2 = "";
                    }
                    if (strURLLink.IndexOf("<SENDERID>") != -1)
                    {
                        strURLLink = strURLLink.Replace("<SENDERID>", strSMSParamVal[2].Trim());
                    }
                    else if (strURLLink.IndexOf("<SENDERID1>") != -1 | strURLLink.IndexOf("<SENDERID2>") != -1)
                    {
                        strURLLink = strURLLink.Replace("<SENDERID1>", strFromNo1).Replace("<SENDERID2>", strFromNo2);
                    }
                }
                strURLLink = strURLLink.Replace("<MESSAGE>", strMsgTxt);

                if (strURLLink.IndexOf("/opted.smsapi.org/v1.0.7/") != -1)
                {
                    strURLLink = strURLLink.Replace("<MESSAGE>", strMsgTxt);
                }

                if (strURLLink.IndexOf("/174.143.34.193/") != -1)
                {
                    if (strMsgTxt.Trim().Length > 160)
                    {
                        strURLLink = strURLLink + "&mt=4";
                    }
                    else
                    {
                        strURLLink = strURLLink + "&mt=0";
                    }
                    strURLLink = strURLLink + "&typeofmessage=1";
                }

                if (GetSysParmSt("SMSCOUNTRYCD", "") == "Y")
                {
                    if (strMobileNo.Trim().Length == 10)
                    {
                        strMobileNo = "91" + strMobileNo;
                    }
                }
                else if (strMobileNo.Trim().Length > 10)
                {
                    strMobileNo = Strings.Right(strMobileNo.Trim(), 10);
                }
                strURLLink = strURLLink.Replace("<CLIENTMOBILE>", strMobileNo.Trim());

                if (strURLLink.IndexOf("myvaluefirst.com") != -1)
                {
                    string strSENDER = "";
                    if (strSMSParamVal[2].Trim().IndexOf("|") != -1)
                    {
                        if (Strings.Left(strMobileNo.Trim(), 2) == "92" | Strings.Left(strMobileNo.Trim(), 2) == "93")
                        {
                            strSENDER = strSMSParamVal[2].Trim().Split("|")[1];
                        }
                        else
                        {
                            strSENDER = strSMSParamVal[2].Trim().Split("|")[0];
                        }
                    }
                    else
                    {
                        strSENDER = Strings.Left(strSMSParamVal[2].Trim(), 10);
                    }
                    strURLLink = strURLLink.Replace("<SENDERID3>", strSENDER);
                }

                if (GetWebParameter("SECURITYPROT").Trim() == "TLS12")
                {
                    ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072;
                }

                string content = "";

                try
                {
                    HttpWebRequest http = (HttpWebRequest)WebRequest.Create(strURLLink);
                    ServicePointManager.Expect100Continue = true;
                    HttpWebResponse response = (HttpWebResponse)http.GetResponse();
                    var sr = new StreamReader(response.GetResponseStream());
                    content = sr.ReadToEnd();
                    strresponse = content;

                    if (response.StatusCode == HttpStatusCode.OK)
                    {
                        strresponse = "SMS Sent Successfully.";
                    }
                    else if (Strings.InStr(1, content, "<ERROR>") > 0)
                    {
                        if (Strings.InStr(1, strresponse, "<DESC>") > 0)
                        {
                            strresponse = Strings.Mid(content, Strings.InStr(1, content, "<DESC>") + 6);
                            strresponse = Strings.Left(content, Strings.InStr(1, content, "</DESC>") - 1);
                        }
                        else
                        {
                            strresponse = "SMS Sent Successfully.";
                        }
                    }
                    else if (Strings.InStr(1, content, "\"error-status\":\"Success\"") > 0)
                    {
                        strresponse = "SMS Sent Successfully.";
                    }
                    else if (Strings.InStr(1, content, Strings.Trim(strMobileNo)) > 0)
                    {
                        strresponse = "Message Send Successfully.";
                    }
                    else if (Strings.InStr(1, content, "<sms>") > 0)
                    {
                        if (Strings.InStr(1, content, "-1") > 0)
                        {
                            strresponse = "Message Sending Failed";
                        }
                        else if (Strings.InStr(1, Strings.UCase(content), Strings.UCase("Invalid Username Or Password")) > 0)
                        {
                            strresponse = "Sending Failed. Invalid Username Or Password.";
                        }
                        else
                        {
                            strresponse = "Message Send Successfully.";
                        }
                    }
                    else if (Strings.InStr(1, Strings.UCase(content), "FAIL") > 0)
                    {
                        strresponse = "Message Sending Failed";
                    }
                    else if (Strings.InStr(1, Strings.UCase(content), "INVALID USERNAME OR PASSWORD") > 0 | Strings.InStr(1, Strings.UCase(content), "INVALID USERNAME AND PASSWORD") > 0)
                    {
                        strresponse = "Message Sending Failed. Invalid Username Or Password.";
                    }
                    else if (Strings.InStr(1, Strings.UCase(content), "1701|") > 0 | Strings.InStr(1, Strings.UCase(content), "SUCCESS") > 0)
                    {
                        strresponse = "Message Send Successfully.";
                    }
                    else if (Strings.InStr(1, Strings.UCase(content), ":") > 0)
                    {
                        if (string.IsNullOrEmpty(Strings.Split(Strings.UCase(content), ":")[1]))
                        {
                            strresponse = content;
                        }
                        else
                        {
                            strresponse = "Message Send Successfully.";
                        }
                    }
                    else if (content == "100")
                    {
                        strresponse = "Message Send Successfully.";
                    }
                    else if (Strings.InStr(1, Strings.UCase(content), "GID") > 0)
                    {
                        strresponse = "Message Send Successfully.";
                    }
                    else
                    {
                        strresponse = content;
                    }
                }
                catch (Exception e)
                {
                    return e.Message.ToString();
                }

                if (Convert.ToInt16(fnFireQuery("SysObjects", "count(*)", "name", "SMS_Logs", true)) == 0)
                {
                    strsql = "";
                    strsql += " CREATE TABLE [dbo].[SMS_Logs]( ";
                    strsql += " [sl_CmCd] [char](16) NOT NULL, ";
                    strsql += " [sl_Mobile] [char](15) NOT NULL, ";
                    strsql += " [sl_Message] [varchar](2000) NOT NULL, ";
                    strsql += " [sl_Response] [char](150) NOT NULL, ";
                    strsql += " [mkrid] [char](8) NOT NULL, ";
                    strsql += " [mkrdt] [char](8) NOT NULL, ";
                    strsql += " [mkrtm] [char](8) NOT NULL )";
                    ExecuteSQL(strsql);
                }

                strsql = "Insert into sms_Logs values(";
                strsql += "'" + clientCd.ToUpper() + "','" + strMobileNo + "','" + strMsgTxt + "',";
                strsql += "'" + strresponse.Replace("'", " ") + "','" + clientCd.ToUpper() + "',Convert(char,getdate(),112),Convert(char,getdate(),108))";
                ExecuteSQL(strsql);

                return strresponse;
            }
            catch (Exception ex)
            {
                return ex.Message.ToString();
            }
        }

        public dynamic SendEmail_OTP(string userId, string toEmail, string subject, string bodyText, bool smsLog)
        {
            if (!string.IsNullOrEmpty(GetWebParameter("SMTPSERVER").Trim()))
            {
                try
                {
                    string strHost = string.Empty;
                    int intPort;
                    string strUserID = string.Empty;
                    string strPWD = string.Empty;
                    string strEmail = string.Empty;
                    string strSSL = string.Empty;
                    string strSMTPParamVal = GetWebParameter("SMTPSERVER");
                    string strEmailID = toEmail;

                    strHost = strSMTPParamVal.Split('/')[0];
                    intPort = Convert.ToInt32(strSMTPParamVal.Split('/')[1]);
                    strUserID = strSMTPParamVal.Split('/')[2];
                    strPWD = strSMTPParamVal.Split('/')[3];
                    strEmail = strSMTPParamVal.Split('/')[4];
                    strSSL = strSMTPParamVal.Split('/')[5];

                    MailMessage Msg = new MailMessage();

                    Msg.From = new MailAddress(strEmail);
                    Msg.To.Add(strEmailID);
                    Msg.Subject = subject;
                    Msg.Body = bodyText;
                    Msg.IsBodyHtml = true;
                    SmtpClient smtp = new SmtpClient();
                    smtp.Host = strHost;
                    smtp.Port = intPort;
                    smtp.UseDefaultCredentials = false;
                    smtp.Credentials = new System.Net.NetworkCredential(strUserID, strPWD);
                    smtp.EnableSsl = strSSL == "N" ? false : true;
                    System.Net.ServicePointManager.ServerCertificateValidationCallback = delegate (object s,
                    System.Security.Cryptography.X509Certificates.X509Certificate certificate,
                    System.Security.Cryptography.X509Certificates.X509Chain chain,
                    System.Net.Security.SslPolicyErrors sslPolicyErrors)
                    {
                        return true;
                    };
                    smtp.Send(Msg);
                    if (smsLog == false)
                    {
                        string Strsql = "Insert into sms_Logs values(";
                        Strsql += "'" + userId.ToUpper() + "',Left('" + strEmailID + "',15),'" + bodyText + "',";
                        Strsql += "'OTP sent successfully','" + userId.ToUpper() + "','" + DateTime.Now.ToString("yyyyMMdd") + "','" + DateTime.Now.ToString("HH:mm:ss") + "')";
                        ExecuteSQL(Strsql);
                        return "OTP sent on Email successfully!";
                    }
                }
                catch (Exception ex)
                {
                    //finalResponse = "OTP sent successfully!";
                    return " Error while sending otp on Email: " + ex.Message.ToString();
                }
            }
            else
            {
                return " SMTP details not found.";
            }
            return "Something went wrong!";
        }

        public string VerifyOtp_OtpMaster(string userId, string strOTP, string mobile_Email, string modeType, string product)
        {
            try
            {
                ////// Check otp
                string checkOTP = "", strIdentity = "", strMobileNo = "", OTP = strOTP;
                int maxOtpFailCount = 0;
                string Strsql = "select top 1 OTP_Identity,OTP_OTP,OTP_ValidTillDate,OTP_ValidTillTime, OTP_SentTo, OTP_NFiller1  from OTP_Master with (NoLock) where OTP_ClientCode='" + userId + "' and OTP_Status='P' and OTP_Product='" + product + "' and OTP_Type = '" + modeType + "' and OTP_SentTo = '" + mobile_Email + "' order by OTP_Identity desc";
                DataTable dtOtp = OpenDataTable(Strsql);
                if (dtOtp.Rows.Count > 0)
                {
                    checkOTP = dtOtp.Rows[0]["OTP_OTP"].ToString().Trim();
                    strIdentity = dtOtp.Rows[0]["OTP_Identity"].ToString().Trim();
                    strMobileNo = dtOtp.Rows[0]["OTP_SentTo"].ToString().Trim();
                    maxOtpFailCount = Convert.ToInt32(dtOtp.Rows[0]["OTP_NFiller1"].ToString());
                }
                if (maxOtpFailCount >= 3)
                {
                    return "Maximum OTP attempts reached. Please generate a new OTP.";
                }
                else if (!string.IsNullOrWhiteSpace(OTP) && !string.IsNullOrWhiteSpace(checkOTP) && OTP == checkOTP)
                {
                    DateTime dtNow = GetSqlCurrentDateTime();
                    DateTime dt3 = stod(dtOtp.Rows[0]["OTP_ValidTillDate"].ToString());
                    TimeSpan time = TimeSpan.Parse(dtOtp.Rows[0]["OTP_ValidTillTime"].ToString());
                    DateTime dtExpiry = dt3 + time;
                    if (dtNow > dtExpiry)
                    {
                        Strsql = "update OTP_Master set OTP_Status='E' where OTP_Identity='" + strIdentity + "'";
                        ExecuteSQL(Strsql);
                        return "OTP has been expired";
                    }
                    Strsql = "update OTP_Master set OTP_Status='M' where OTP_Identity='" + strIdentity + "'";
                    ExecuteSQL(Strsql);
                }
                else
                {
                    Strsql = "update OTP_Master set OTP_NFiller1=" + (maxOtpFailCount + 1) + " where OTP_Identity='" + strIdentity + "'";
                    ExecuteSQL(Strsql);
                    return "OTP Mismatched";
                }
            }
            catch (Exception)
            {
            }
            return "success";
        }

        public bool VerifySignature(string payload, string publicKeyBase64, string signatureBase64)
        {
            byte[] publicKeyBytes = Convert.FromBase64String(publicKeyBase64);
            byte[] payloadBytes = Encoding.UTF8.GetBytes(payload);
            byte[] signatureBytes = Convert.FromBase64String(signatureBase64);

            using (RSA rsa = RSA.Create())
            {
                rsa.ImportSubjectPublicKeyInfo(publicKeyBytes, out _); // Import PKCS#8 public key

                return rsa.VerifyData(payloadBytes, signatureBytes, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
            }
        }

        private T ParseJsonFromXml<T>(XmlDocument xml, string tagName, out string errorMessage) where T : class
        {
            errorMessage = null;
            string jsonString = xml.GetElementsByTagName(tagName)[0]?.InnerText;

            if (string.IsNullOrWhiteSpace(jsonString))
            {
                errorMessage = $"{tagName} element is empty or missing.";
                return null;
            }

            jsonString = "{" + jsonString.Replace("\u201C", "\"").Replace("\u201D", "\"") + "}";

            try
            {
                return JsonConvert.DeserializeObject<T>(jsonString);
            }
            catch (JsonException ex)
            {
                errorMessage = $"Invalid JSON in {tagName} element: {ex.Message}";
                return null;
            }
        }

        private void UpdateXmlNodeWithJson(XmlDocument xml, string tagName, object jsonObject)
        {
            XmlNode node = xml.DocumentElement[tagName];
            if (node != null)
            {
                string jsonString = JsonConvert.SerializeObject(jsonObject)
                    .Replace("{", "").Replace("}", ""); // Remove enclosing braces
                node.InnerText = jsonString;
            }
        }

        public string EDIS_Encrypt(string plainText, string KeyString)
        {
            byte[] key = ASCIIEncoding.UTF8.GetBytes(KeyString);
            byte[] iv = new byte[16] { 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0 };
            // Instantiate a new Aes object to perform string symmetric encryption
            Aes encryptor = Aes.Create();

            encryptor.Mode = CipherMode.CBC;
            //encryptor.KeySize = 256;
            //encryptor.BlockSize = 128;
            //encryptor.Padding = PaddingMode.Zeros;

            // Set key and IV
            encryptor.Key = key.Take(32).ToArray();
            encryptor.IV = iv;

            // Instantiate a new MemoryStream object to contain the encrypted bytes
            MemoryStream memoryStream = new MemoryStream();

            // Instantiate a new encryptor from our Aes object
            ICryptoTransform aesEncryptor = encryptor.CreateEncryptor();

            // Instantiate a new CryptoStream object to process the data and write it to the 
            // memory stream
            CryptoStream cryptoStream = new CryptoStream(memoryStream, aesEncryptor, CryptoStreamMode.Write);

            // Convert the plainText string into a byte array
            byte[] plainBytes = Encoding.ASCII.GetBytes(plainText);

            // Encrypt the input plaintext string
            cryptoStream.Write(plainBytes, 0, plainBytes.Length);

            // Complete the encryption process
            cryptoStream.FlushFinalBlock();

            // Convert the encrypted data from a MemoryStream to a byte array
            byte[] cipherBytes = memoryStream.ToArray();

            // Close both the MemoryStream and the CryptoStream
            memoryStream.Close();
            cryptoStream.Close();

            // Convert the encrypted byte array to a base64 encoded string
            string cipherText = Convert.ToBase64String(cipherBytes, 0, cipherBytes.Length);

            // Return the encrypted data as a string
            return cipherText;
        }

        public string EDIS_Decrypt(string cipherText, string KeyString)
        {
            try
            {
                byte[] key = ASCIIEncoding.UTF8.GetBytes(KeyString);
                byte[] iv = new byte[16] { 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0 };

                // Instantiate a new Aes object to perform string symmetric encryption
                Aes decryptor = Aes.Create();

                decryptor.Mode = CipherMode.CBC;
                decryptor.Key = key.Take(32).ToArray();
                decryptor.IV = iv;

                // Instantiate a new MemoryStream object to contain the decrypted bytes
                MemoryStream memoryStream = new MemoryStream();

                // Instantiate a new decryptor from our Aes object
                ICryptoTransform aesDecryptor = decryptor.CreateDecryptor();

                // Instantiate a new CryptoStream object to process the data and write it to the memory stream
                CryptoStream cryptoStream = new CryptoStream(memoryStream, aesDecryptor, CryptoStreamMode.Write);

                // Convert the base64-encoded string to a byte array
                byte[] cipherBytes = Convert.FromBase64String(cipherText);

                // Decrypt the input ciphertext bytes
                cryptoStream.Write(cipherBytes, 0, cipherBytes.Length);

                // Complete the decryption process
                cryptoStream.FlushFinalBlock();

                // Convert the decrypted data from a MemoryStream to a byte array
                byte[] plainBytes = memoryStream.ToArray();

                // Close both the MemoryStream and the CryptoStream
                memoryStream.Close();
                cryptoStream.Close();

                // Convert the decrypted byte array to a string using ASCII encoding
                string plainText = Encoding.ASCII.GetString(plainBytes);

                // Return the decrypted data as a string
                return plainText;
            }
            catch (Exception ex)
            {
                // Handle decryption errors, e.g., incorrect key or corrupted data
                Console.WriteLine("Decryption error: " + ex.Message);
                return null;
            }
        }

        public VersionInfo GetVersionInfo(VersionData versionData, SqlConnection sqlcon = null)
        {
            try
            {
                string strFormat = "yyyyMMddHHmmss";
                var culture = System.Globalization.CultureInfo.InvariantCulture;
                var style = System.Globalization.DateTimeStyles.None;

                string strPath = Path.Combine(Directory.GetCurrentDirectory(), "SQL", versionData.ApplicationName + ".sql");
                DateTime LastWriteTime = File.GetLastWriteTime(strPath);
                LastWriteTime = new DateTime(LastWriteTime.Year, LastWriteTime.Month, LastWriteTime.Day, LastWriteTime.Hour, LastWriteTime.Minute, LastWriteTime.Second);

                string strLocalSPFileDate = LastWriteTime.ToString("yyyyMMddHHmmss");
                string strParamSPDate = "";
                string strParamQueryDate = "";
                if (sqlcon == null)
                {
                    strParamSPDate = GetWebParameter(versionData.ApplicationName + "SPDT");
                    strParamQueryDate = GetWebParameter(versionData.ApplicationName + "DBDT");
                }
                else
                {
                    strParamSPDate = GetWebParameter(versionData.ApplicationName + "SPDT", sqlcon);
                    strParamQueryDate = GetWebParameter(versionData.ApplicationName + "DBDT", sqlcon);
                }
                string strWebSPDate = versionData.SPDate;
                string strWebSPStatus = "";
                string strWebQueryDate = versionData.DBDate;

                ParseVersion(strWebSPDate, out strWebSPDate, out strWebSPStatus);

                DateTime LocalSPFileDate, ParamSPDate, ParamQueryDate, WebSPDate, WebQueryDate;

                bool isLocalSPDateValid = DateTime.TryParseExact(strLocalSPFileDate, strFormat, culture, style, out LocalSPFileDate);
                bool isParamDateValid = DateTime.TryParseExact(strParamSPDate, strFormat, culture, style, out ParamSPDate);
                bool isQueryDateValid = DateTime.TryParseExact(strParamQueryDate, strFormat, culture, style, out ParamQueryDate);
                bool isWebDBDateValid = DateTime.TryParseExact(strWebSPDate, strFormat, culture, style, out WebSPDate);
                bool isWebQueryDateValid = DateTime.TryParseExact(strWebQueryDate, strFormat, culture, style, out WebQueryDate);

                return new VersionInfo
                {
                    LocalSPFileDate = LocalSPFileDate,
                    ParamSPFileDate = ParamSPDate,
                    WebSPFileDate = WebSPDate,
                    WebSPFileStatus = strWebSPStatus,
                    ParamDBDate = ParamQueryDate,
                    WebDBDate = WebQueryDate
                };
            }
            catch (Exception)
            {
                throw;
            }
        }

        public void ParseVersion(string versionInput, out string version, out string status)
        {
            if (!string.IsNullOrEmpty(versionInput) && versionInput.Contains("~"))
            {
                string[] parts = versionInput.Split('~');
                version = parts[0];
                status = parts.Length > 1 ? parts[1] : "O";
            }
            else
            {
                version = versionInput;
                status = "O";
            }
        }

        public void CheckSPNew(string strParamCode, SqlConnection conn = null)
        {
            try
            {
                string strsql = "";
                string strPath = Path.Combine(Directory.GetCurrentDirectory(), "SQL", strParamCode + ".sql");

                if (!File.Exists(strPath))
                {
                    return;
                }

                DateTime LastWriteTime = File.GetLastWriteTime(strPath);
                //removing milliseconds for comparision
                LastWriteTime = new DateTime(LastWriteTime.Year, LastWriteTime.Month, LastWriteTime.Day, LastWriteTime.Hour, LastWriteTime.Minute, LastWriteTime.Second);

                //var db = new DataContext();
                SqlConnection sqlCon = conn ?? new SqlConnection(_connStr);
                bool blnShouldClose = false;

                if (conn == null)
                {
                    blnShouldClose = true;
                }
                if (sqlCon.State == ConnectionState.Closed)
                {
                    sqlCon.Open();
                }

                // Read the content of the .sql file
                string sqlScript = "";

                using (StreamReader reader = new StreamReader(strPath, Encoding.UTF8))
                {
                    string strFileText = reader.ReadToEnd();
                    //string strEnc = Convert.ToBase64String(EncryptStringToBytes_Aes(strFileText, Encoding.UTF8.GetBytes("5F4E3D2C1B0A9876"), Encoding.UTF8.GetBytes("7A6B5C4D3E2F1A09")));
                    sqlScript = DecryptStringFromBytes_Aes(Convert.FromBase64String(strFileText), Encoding.UTF8.GetBytes("5F4E3D2C1B0A9876"), Encoding.UTF8.GetBytes("7A6B5C4D3E2F1A09"));
                }
                string[] batches = Regex.Split(sqlScript, @"^\s*GO\s*$", RegexOptions.Multiline);

                foreach (string batch in batches)
                {
                    if (batch.Trim() != "")
                    {
                        try
                        {
                            Match match = Regex.Match(batch, @"CREATE\s+(?<type>PROCEDURE|FUNCTION|TYPE)\s+(?:(?:\[(?<schema>\w+)\]|(?<schema>\w+))\.)?(?:\[(?<name>\w+)\]|(?<name>\w+))", RegexOptions.IgnoreCase);

                            if (match.Success)
                            {
                                string objectType = match.Groups["type"].Value.ToUpper();
                                string schema = match.Groups["schema"].Success ? match.Groups["schema"].Value : "dbo";
                                string objectName = $"{schema}.{match.Groups["name"].Value}";

                                string checkQuery = "";
                                if (objectType == "TYPE")
                                {
                                    checkQuery = @"SELECT COUNT(*) FROM sys.table_types WHERE name = @Name AND schema_id = SCHEMA_ID(@Schema)";
                                }
                                else
                                {
                                    checkQuery = @"SELECT COUNT(*) FROM sys.objects WHERE object_id = OBJECT_ID(@ObjectName)";
                                }
                                using SqlCommand checkCmd = new SqlCommand(checkQuery, conn);
                                if (objectType == "TYPE")
                                {
                                    checkCmd.Parameters.AddWithValue("@Name", match.Groups["name"].Value);
                                    checkCmd.Parameters.AddWithValue("@Schema", schema);
                                }
                                else
                                {
                                    checkCmd.Parameters.AddWithValue("@ObjectName", objectName);
                                }
                                int exists = Convert.ToInt32(checkCmd.ExecuteScalar());

                                if (exists > 0)
                                {
                                    continue;
                                }
                            }

                            using SqlCommand command = new SqlCommand(batch, sqlCon);
                            command.ExecuteNonQuery();
                        }
                        catch (SqlException)
                        {
                            throw;
                        }
                    }
                }

                if (Convert.ToInt16(fnFireQueryTradeWeb("webparameter", "count(0)", "sp_parmcd", strParamCode + "SPDT", true, sqlCon)) > 0)
                {
                    strsql = "update webparameter set sp_sysvalue = '" + LastWriteTime.ToString("yyyyMMddHHmmss") + "' where sp_parmcd='" + strParamCode + "SPDT'";
                }
                else
                {
                    strsql = "Insert into Webparameter values('" + strParamCode + "SPDT', '" + strParamCode + " SP Date', '" + LastWriteTime.ToString("yyyyMMddHHmmss") + "')";
                }
                ExecuteSQL(strsql, sqlCon);

                if (blnShouldClose)
                {
                    sqlCon.Dispose();
                }
                return;
            }
            catch (Exception)
            {
                throw;
            }
        }

        public (string Status, string Message) InsertOTP(string clientCd, string strSotp, string strMobileNo, string strItem, string Product, string Mode, int intOTPValidTime, SqlConnection objConnection)
        {
            try
            {
                int intAttempts = 10;
                int intMinutes = 15;
                string strParmOTP = GetWebParameter("OTPMAXATMPT");
                if (!string.IsNullOrWhiteSpace(strParmOTP) && strParmOTP.Contains("~"))
                {
                    var parts = strParmOTP.Split('~');
                    if (parts.Length == 2)
                    {
                        int.TryParse(parts[0], out intAttempts);
                        int.TryParse(parts[1], out intMinutes);
                    }
                }

                string strsql = @"
                BEGIN TRANSACTION;

                IF (
                    SELECT COUNT(1)
                    FROM OTP_Master WITH (UPDLOCK, HOLDLOCK)
                    WHERE OTP_ClientCode = @ClientCode
                      AND OTP_Product = @Product
                      AND OTP_Type = @Mode
                      AND CAST(OTP_SentDate AS DATETIME) + CAST(OTP_SentTime AS DATETIME)
                          >= DATEADD(MINUTE, -@LimitMinutes, GETDATE())
                ) < @MaxAttempts
                BEGIN
                    UPDATE OTP_Master
                    SET OTP_Status = 'E'
                    WHERE OTP_ClientCode = @ClientCode
                      AND OTP_Product = @Product
                      AND OTP_Type = @Mode
                      AND OTP_Status = 'P';

                    INSERT INTO OTP_Master (
                        OTP_ClientCode, OTP_Item, OTP_OTP, OTP_SentTo,
                        OTP_SentDate, OTP_SentTime, OTP_ValidTillDate, OTP_ValidTillTime,
                        OTP_Status, OTP_Product, OTP_Type,
                        OTP_Filler1, OTP_Filler2, OTP_Filler3,
                        OTP_NFiller1, OTP_NFiller2, OTP_NFiller3
                    )
                    VALUES (
                        @ClientCode, @Item, @OtpValue, @MobileNo,
                        CONVERT(CHAR(8), GETDATE(), 112), CONVERT(VARCHAR(8), GETDATE(), 108),
                        CONVERT(CHAR(8), DATEADD(MINUTE, @ValidMinutes, GETDATE()), 112),
                        CONVERT(VARCHAR(8), DATEADD(MINUTE, @ValidMinutes, GETDATE()), 108),
                        'P', @Product, @Mode,
                        '', '', '', 0, 0, 0
                    );

                    COMMIT TRANSACTION;
                    SELECT 1; --Success
                END
                ELSE
                BEGIN
                    ROLLBACK TRANSACTION;
                    SELECT 0; --Too many attempts
                END";

                SqlCommand cmd1 = new SqlCommand(strsql, objConnection);
                cmd1.Parameters.AddWithValue("@ClientCode", clientCd.ToUpper());
                cmd1.Parameters.AddWithValue("@OtpValue", strSotp.Trim());
                cmd1.Parameters.AddWithValue("@MobileNo", strMobileNo);
                cmd1.Parameters.AddWithValue("@Item", strItem);
                cmd1.Parameters.AddWithValue("@Product", Product);
                cmd1.Parameters.AddWithValue("@Mode", Mode);
                cmd1.Parameters.AddWithValue("@ValidMinutes", intOTPValidTime);
                cmd1.Parameters.AddWithValue("@LimitMinutes", intMinutes);
                cmd1.Parameters.AddWithValue("@MaxAttempts", intAttempts);

                object result = cmd1.ExecuteScalar();

                if (Convert.ToInt32(result) <= 0)
                {
                    // Get most recent OTP timestamp for wait time
                    strsql = @"
                    SELECT TOP 1 
                    CAST(OTP_SentDate AS DATETIME) + CAST(OTP_SentTime AS DATETIME) AS LastSent
                    FROM OTP_Master
                    WHERE OTP_ClientCode = @ClientCode
                    AND OTP_Product = @Product
                    AND OTP_Type = @Mode
                    AND CAST(OTP_SentDate AS DATETIME) + CAST(OTP_SentTime AS DATETIME) 
                    >= DATEADD(MINUTE, -@LimitMinutes, GETDATE())
                    ORDER BY OTP_SentDate DESC, OTP_SentTime DESC;";

                    cmd1 = new SqlCommand(strsql, objConnection);
                    cmd1.Parameters.AddWithValue("@ClientCode", clientCd.ToUpper());
                    cmd1.Parameters.AddWithValue("@Product", Product);
                    cmd1.Parameters.AddWithValue("@Mode", Mode);
                    cmd1.Parameters.AddWithValue("@LimitMinutes", intMinutes);

                    object lastSentObj = cmd1.ExecuteScalar();

                    if (lastSentObj != null && DateTime.TryParse(lastSentObj.ToString(), out DateTime lastSent))
                    {
                        DateTime nextAllowed = lastSent.AddMinutes(intMinutes);
                        TimeSpan remaining = nextAllowed - DateTime.Now;

                        if (remaining.TotalSeconds > 0)
                        {
                            int minutes = (int)remaining.TotalMinutes;
                            int seconds = remaining.Seconds;
                            string waitTimeMsg = $"Too many OTP attempts. Try again after {minutes} minute(s) and {seconds} second(s).";

                            return (Status: "N", Message: waitTimeMsg);
                        }
                    }

                    return (Status: "N", Message: "Too many OTP attempts. Try after some time.");
                }

                return (Status: "Y", Message: "");
            }
            catch (Exception ex)
            {
                return (Status: "N", Message: "Error : " + ex.Message);
            }
        }

        public string GenerateRefreshToken(string UserId, string LoginAs, string Role, int ExpiryTime)
        {
            string Strsql = "";
            if (!fnchkTable("RefreshTokens"))
            {
                Strsql = " CREATE TABLE RefreshTokens(" +
                         " [Id] [int] IDENTITY(1,1) NOT NULL, " +
                         " [UserCode] [varchar](16) NOT NULL, " +
                         " [UserType] [char](1) NOT NULL, " +
                         " [Role] [varchar](20) NOT NULL, " +
                         " [Token] [nvarchar](500) NOT NULL, " +
                         " [ExpiryDate] [datetime] NOT NULL, " +
                         " [IsRevoked] [bit] NOT NULL, " +
                         " [Filler1] [char](1) NOT NULL, " +
                         " [Filler2] [char](1) NOT NULL, " +
                         " [Filler3] [char](1) NOT NULL, " +
                         " [NFiller1] [numeric](18, 0) NOT NULL, " +
                         " [NFiller2] [numeric](18, 0) NOT NULL, " +
                         " [NFiller3] [numeric](18, 0) NOT NULL, " +
                         " CONSTRAINT [PK_RefreshTokens] PRIMARY KEY CLUSTERED " +
                         " ( " +
                         "    [Id] ASC" +
                         ")" +
                         ")";
                ExecuteSQL(Strsql);

                Strsql = "CREATE NONCLUSTERED INDEX indx1_RefreshTokens ON RefreshTokens(UserCode, UserType); ";
                ExecuteSQL(Strsql);
            }

            var randomNumber = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(randomNumber);
                string strRefToken = Convert.ToBase64String(randomNumber);

                Strsql = "update RefreshTokens set IsRevoked = 1 where UserCode = '" + UserId + "' and UserType = '" + LoginAs + "' and IsRevoked = 0";
                ExecuteSQL(Strsql);

                Strsql = "Insert into RefreshTokens values('" + UserId + "', '" + LoginAs + "', '" + Role + "', '" + strRefToken + "', DATEADD(minute, " + ExpiryTime + ", GETUTCDATE()), '0', '', '', '', 0, 0, 0)";
                ExecuteSQL(Strsql);

                return strRefToken;
            }
        }

