        public string WebBasedBlocking(string userId, string ipAddress, string strIPMode, string strAcccess, int websrno = 0)
        {
            string strsql = "";
            if (strIPMode == "C")
            {
                return "You Are Trying To Login From Unauthorised Location / System";
            }
            else if (strIPMode == "P")
            {
                if (strAcccess != "N")
                {
                    strsql = " insert into web_ip(web_userid,web_ipfrom,web_access,web_remark,Mkrdt) ";
                    strsql = strsql + " values ('" + userId.ToUpper() + "','" + ipAddress + "','Y','','" + DateTime.Now.ToString("yyyyMMdd") + "')";
                }
                else
                {
                    strsql = " update web_ip set web_access = 'Y' , Mkrdt='" + DateTime.Now.ToString("yyyyMMdd") + "' ";
                    strsql = strsql + " where web_srno = " + websrno;
                }
                ExecuteSQL(strsql);

                return "";
            }
            else if (strIPMode == "A")
            {
                DataSet DsTemp = new DataSet();
                DsTemp = OpenDataSet("select * From Web_IP Where web_userid= '" + userId.ToUpper() + "' and web_access = 'Y'");
                if (DsTemp.Tables[0].Rows.Count > 0)
                {
                    return "You Are Trying To Login From Unauthorised Location / System";
                }
                else
                {
                    return "";
                }

            }
            else if (strIPMode == "B")
            {
                return "You Are Trying To Login From Unauthorised Location / System";
            }
            else
            {
                return "";
            }
        }

        public string Encrypt(string plainText, string Key)
        {
            byte[] iv = new byte[16];
            RandomNumberGenerator.Fill(iv);   // generate random IV

            using (Aes aes = Aes.Create())
            {
                aes.KeySize = 256;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                aes.Key = Convert.FromBase64String(Key);
                aes.IV = iv;

                using var encryptor = aes.CreateEncryptor();
                using var ms = new MemoryStream();
                using var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write);

                byte[] plainBytes = Encoding.UTF8.GetBytes(plainText);
                cs.Write(plainBytes, 0, plainBytes.Length);
                cs.FlushFinalBlock();

                byte[] cipherBytes = ms.ToArray();

                // return IV:CipherText (both Base64)
                return Convert.ToBase64String(iv) + ":" + Convert.ToBase64String(cipherBytes);
            }
        }

        public string Decrypt(string input, string Key)
        {
            var parts = input.Split(':');

            if (parts.Length != 2)
                throw new Exception("Invalid encrypted format. Expected IV:CipherText");

            byte[] iv = Convert.FromBase64String(parts[0]);
            byte[] cipherBytes = Convert.FromBase64String(parts[1]);

            using (Aes aes = Aes.Create())
            {
                aes.KeySize = 256;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                aes.Key = Convert.FromBase64String(Key);
                aes.IV = iv;

                using var decryptor = aes.CreateDecryptor();
                using var ms = new MemoryStream(cipherBytes);
                using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
                using var sr = new StreamReader(cs, Encoding.UTF8);

                return sr.ReadToEnd();
            }
        }

        public List<T> ConvertToList<T>(DataTable dt) where T : new()
        {
            var columnNames = dt.Columns.Cast<DataColumn>()
                                        .Select(c => c.ColumnName.ToLower())
                                        .ToList();

            var properties = typeof(T).GetProperties();

            var list = new List<T>();

            foreach (DataRow row in dt.Rows)
            {
                T obj = new T();

                foreach (var prop in properties)
                {
                    if (columnNames.Contains(prop.Name.ToLower()))
                    {
                        try
                        {
                            var value = row[prop.Name];
                            if (value == DBNull.Value) value = null;

                            prop.SetValue(obj, value);
                        }
                        catch { }
                    }
                }

                list.Add(obj);
            }

            return list;
        }

        public double ToDouble(object value, double defaultValue = 0d)
        {
            if (value == null || value == DBNull.Value)
                return defaultValue;

            var str = Convert.ToString(value);

            return double.TryParse(str,
                                   NumberStyles.Any,
                                   CultureInfo.InvariantCulture,
                                   out double result)
                   ? result
                   : defaultValue;
        }

